    "about.certs.title": {en:"ISO 9001:2015, CE & 60+ Patents",zh:"ISO 9001:2015、CE认证及60多项专利",es:"ISO 9001:2015, CE y 60+ patentes",ru:"ISO 9001:2015, CE и 60+ патентов",ar:"ISO 9001:2015 وCE وأكثر من 60 براءة اختراع",tr:"ISO 9001:2015, CE ve 60+ patent",fr:"ISO 9001:2015, CE et plus de 60 brevets",pt:"ISO 9001:2015, CE e mais de 60 patentes",hi:"ISO 9001:2015, CE और 60+ पेटेंट",id:"ISO 9001:2015, CE & 60+ paten"},
    "about.process.eyebrow": {en:"Quality process",zh:"质量流程",es:"Proceso de calidad",ru:"Процесс контроля качества",ar:"عملية الجودة",tr:"Kalite süreci",fr:"Processus qualité",pt:"Processo de qualidade",hi:"गुणवत्ता प्रक्रिया",id:"Proses kualitas"},
    "about.process.title": {en:"From Sheet Metal to Factory Acceptance Test",zh:"从钢板到工厂验收测试",es:"Del acero en chapa a la prueba de aceptación de fábrica",ru:"От листового металла до приёмочных испытаний",ar:"من الصفائح المعدنية إلى اختبار القبول بالمصنع",tr:"Sac levhadan fabrika kabul testine",fr:"De la tôle au test d'acceptation en usine",pt:"Da chapa metálica ao teste de aceitação em fábrica",hi:"शीट मेटल से फ़ैक्टरी स्वीकृति परीक्षण तक",id:"Dari lembaran logam ke uji penerimaan pabrik"},
    "about.reach.eyebrow": {en:"Global reach",zh:"全球覆盖",es:"Alcance global",ru:"Глобальный охват",ar:"الانتشار العالمي",tr:"Küresel erişim",fr:"Portée mondiale",pt:"Alcance global",hi:"वैश्विक पहुँच",id:"Jangkauan global"},
    "about.reach.title": {en:"5,000+ Machines in 80+ Countries",zh:"80多个国家装机5000余台",es:"Más de 5.000 máquinas en más de 80 países",ru:"5000+ машин в 80+ странах",ar:"أكثر من 5000 آلة في أكثر من 80 دولة",tr:"80+ ülkede 5.000+ makine",fr:"5 000+ machines dans 80+ pays",pt:"5.000+ máquinas em mais de 80 países",hi:"80+ देशों में 5,000+ मशीनें",id:"5.000+ mesin di 80+ negara"},
    "about.video.caption": {en:"No.78 Huanxi Road, Zhutang Town, Jiangyin \u2014 SBKJ\u2019s production facility since 1995.",zh:"江阴市祝塘镇环西路78号 \u2014 SBKJ自1995年起的生产基地。"},
    "about.milestones.lead": {en:"From a small roll\u2011forming workshop in Jiangyin to a global ductwork machinery exporter, SBKJ\u2019s history is the history of Chinese HVAC automation.",zh:"从江阴一家小型辊压成型车间到全球风管机械出口商，SBKJ的历史就是中国暖通自动化的发展史。"},
