    "about.team.mech.2": {en:"Authors of SBTF, SBAL and RDL geometry",zh:"SBTF、SBAL和RDL几何结构的设计者"},
    "about.team.mech.3": {en:"Material expertise: GI, SS304, aluminium, pre\u2011insulated panel",zh:"材料专长：镀锌板、SS304不锈钢、铝板、预绝热板"},
    "about.team.elec.title": {en:"Electrical & PLC integration (4 engineers)",zh:"电气与PLC集成（4名工程师）"},
    "about.team.elec.1": {en:"Siemens S7 & Mitsubishi FX programming",zh:"Siemens S7和Mitsubishi FX编程"},
    "about.team.elec.2": {en:"Servo motion control & CNC plasma integration",zh:"伺服运动控制与CNC等离子集成"},
    "about.team.elec.3": {en:"Safety interlocks to EN ISO 13849 category 3",zh:"符合EN ISO 13849第3类的安全联锁"},
