    "about.team.field.1": {en:"On\u2011site installation across 80+ countries",zh:"覆盖80多个国家的现场安装"},
    "about.team.field.2": {en:"Operator and maintenance training in English",zh:"提供英文操作和维护培训"},
    "about.team.field.3": {en:"First\u2011article duct validation (SMACNA, EN 1505, AS/NZS 4254)",zh:"首件风管验证（SMACNA、EN 1505、AS/NZS 4254）"},
    "about.certs.lead": {en:"Independent third\u2011party certification, documented factory testing and an active patent portfolio \u2014 the evidence behind every SBKJ quote.",zh:"独立的第三方认证、完整记录的工厂测试和活跃的专利组合 \u2014 每份SBKJ报价背后的实力证明。"},
    "about.certs.iso.title": {en:"ISO 9001:2015 quality management",zh:"ISO 9001:2015质量管理"},
    "about.certs.ce.title": {en:"CE marking (Machinery Directive)",zh:"CE认证（机械指令）"},
    "about.certs.patents.title": {en:"60+ invention and utility patents",zh:"60余项发明和实用新型专利"},
    "about.certs.standards.title": {en:"Standards supported",zh:"支持的标准"},
    "about.certs.standards.lead": {en:"Every SBKJ line is configured to produce duct that complies with the international fabrication standard you specify on your order.",zh:"每条SBKJ产线均按照您订单中指定的国际制造标准进行配置，确保生产的风管符合要求。"},
    "about.certs.standards.smacna": {en:"<strong>SMACNA</strong> HVAC Duct Construction Standards (USA & Middle East projects)",zh:"<strong>SMACNA</strong> 暖通风管施工标准（美国及中东项目）"},
    "about.certs.standards.en1505": {en:"<strong>EN 1505 / EN 1506</strong> (European rectangular and circular duct)",zh:"<strong>EN 1505 / EN 1506</strong>（欧洲矩形和圆形风管）"},
    "about.certs.standards.asnzs": {en:"<strong>AS/NZS 4254.1 & 4254.2</strong> (Australia and New Zealand flexible and rigid duct)",zh:"<strong>AS/NZS 4254.1 & 4254.2</strong>（澳大利亚和新西兰柔性及刚性风管）"},
    "about.certs.standards.dw144": {en:"<strong>DW/144</strong> (United Kingdom HVAC duct specification)",zh:"<strong>DW/144</strong>（英国暖通风管规范）"},
    "about.certs.standards.gb": {en:"<strong>GB/T 17713</strong> and <strong>JGJ 141</strong> (China HVAC duct specifications)",zh:"<strong>GB/T 17713</strong> 和 <strong>JGJ 141</strong>（中国暖通风管规范）"},
    "about.quality.step1.title": {en:"Incoming material inspection",zh:"来料检验"},
