    "machines.compare.th.material": {en:"Material",zh:"材料",es:"Material",ru:"Материал",ar:"المادة",tr:"Malzeme",fr:"Matériau",pt:"Material",hi:"सामग्री",id:"Material"},
    "machines.compare.th.width": {en:"Width range",zh:"宽度范围",es:"Rango de ancho",ru:"Диапазон ширины",ar:"نطاق العرض",tr:"Genişlik aralığı",fr:"Plage de largeur",pt:"Faixa de largura",hi:"चौड़ाई रेंज",id:"Rentang lebar"},
