    "factory.eyebrow": {en:"Factory capability",zh:"工厂实力",es:"Capacidad de fábrica",ru:"Возможности завода",ar:"قدرات المصنع",tr:"Fabrika kapasitesi",fr:"Capacités de l'usine",pt:"Capacidade da fábrica",hi:"फैक्ट्री क्षमता",id:"Kapasitas pabrik"},
    "factory.title": {en:"Inside the SBKJ Jiangyin Factory",zh:"走进SBKJ江阴工厂",es:"Dentro de la Fábrica SBKJ Jiangyin",ru:"Внутри завода SBKJ в Цзянъине",ar:"داخل مصنع SBKJ جيانغيين",tr:"SBKJ Jiangyin Fabrikasının İçinde",fr:"À l'intérieur de l'usine SBKJ Jiangyin",pt:"Dentro da Fábrica SBKJ Jiangyin",hi:"SBKJ जियांगयिन फैक्ट्री के अंदर",id:"Di dalam Pabrik SBKJ Jiangyin"},
    "factory.lead": {en:"A purpose-built HVAC duct machinery factory in Jiangyin, China — 30,000 m² of machining, assembly and testing under one roof. ISO 9001:2015 certified since 2007.",zh:"位于中国江阴的专业暖通风管设备制造工厂 — 30,000平方米的加工、装配和测试区域集中于同一屋檐下。自2007年起通过ISO 9001:2015认证。",es:"Una fábrica de maquinaria HVAC especialmente construida en Jiangyin, China — 30.000 m² de mecanizado, ensamblaje y pruebas bajo un mismo techo.",ru:"Специализированный завод HVAC-оборудования в Цзянъине, Китай — 30 000 м² механической обработки, сборки и испытаний под одной крышей.",ar:"مصنع متخصص لآلات مجاري الهواء HVAC في جيانغيين، الصين — 30,000 م² من التصنيع والتجميع والاختبار تحت سقف واحد.",tr:"Çin Jiangyin'de amaca yönelik inşa edilmiş bir HVAC kanal makineleri fabrikası — 30.000 m² işleme, montaj ve test alanı tek bir çatı altında.",fr:"Une usine de machines HVAC construite à cet effet à Jiangyin, Chine — 30 000 m² d'usinage, d'assemblage et de tests sous un même toit.",pt:"Uma fábrica de máquinas HVAC construída especificamente em Jiangyin, China — 30.000 m² de usinagem, montagem e testes sob um mesmo teto.",hi:"चीन के जियांगयिन में उद्देश्य-निर्मित HVAC डक्ट मशीनरी फैक्ट्री — एक ही छत के नीचे 30,000 m² मशीनिंग, असेंबली और परीक्षण।",id:"Pabrik mesin saluran HVAC yang dibangun khusus di Jiangyin, Tiongkok — 30.000 m² permesinan, perakitan, dan pengujian di bawah satu atap."},
    "factory.lines.title": {en:"Three Complete Lines for Every HVAC Duct Need",zh:"三条完整生产线，满足所有暖通风管需求",es:"Tres Líneas Completas para Toda Necesidad de Conductos HVAC",ru:"Три полные линии для любых задач HVAC",ar:"ثلاثة خطوط كاملة لكل احتياجات مجاري الهواء HVAC",tr:"Her HVAC Kanal İhtiyacı için Üç Komple Hat",fr:"Trois lignes complètes pour tous les besoins HVAC",pt:"Três Linhas Completas para Todas as Necessidades HVAC",hi:"हर HVAC डक्ट आवश्यकता के लिए तीन पूर्ण लाइनें",id:"Tiga Jalur Lengkap untuk Setiap Kebutuhan Saluran HVAC"},
    "factory.line1": {en:"Spiral Duct Forming",zh:"螺旋风管成型",es:"Formación de Conductos Espirales",ru:"Спиральные воздуховоды",ar:"تشكيل القنوات الحلزونية",tr:"Spiral Kanal Şekillendirme",fr:"Formage de conduits spiralés",pt:"Formação de Dutos Espirais",hi:"स्पाइरल डक्ट फॉर्मिंग",id:"Pembentukan Saluran Spiral"},
