    "factory.line3": {en:"Auto Duct Production Lines",zh:"全自动风管生产线",es:"Líneas Automáticas de Producción de Conductos",ru:"Автоматические линии производства воздуховодов",ar:"خطوط إنتاج القنوات الأوتوماتيكية",tr:"Otomatik Kanal Üretim Hatları",fr:"Lignes de production automatiques de conduits",pt:"Linhas Automáticas de Produção de Dutos",hi:"स्वचालित डक्ट उत्पादन लाइनें",id:"Jalur Produksi Saluran Otomatis"},

    /* ---- Quality Page ---- */
    "quality.eyebrow": {en:"Quality assurance",zh:"质量保证",es:"Garantía de calidad",ru:"Контроль качества",ar:"ضمان الجودة",tr:"Kalite güvencesi",fr:"Assurance qualité",pt:"Garantia de qualidade",hi:"गुणवत्ता आश्वासन",id:"Jaminan kualitas"},
    "quality.title": {en:"How SBKJ Ensures Machine Quality",zh:"SBKJ如何确保设备质量",es:"Cómo SBKJ Garantiza la Calidad",ru:"Как SBKJ обеспечивает качество оборудования",ar:"كيف تضمن SBKJ جودة الآلات",tr:"SBKJ Makine Kalitesini Nasıl Sağlar",fr:"Comment SBKJ garantit la qualité des machines",pt:"Como a SBKJ Garante a Qualidade",hi:"SBKJ मशीन गुणवत्ता कैसे सुनिश्चित करती है",id:"Bagaimana SBKJ Memastikan Kualitas Mesin"},
    "quality.lead": {en:"ISO 9001:2015 certified since 2007. Every machine passes a documented Factory Acceptance Test (FAT) before it ships, with serialized QA records traceable for the full warranty period.",zh:"自2007年起通过ISO 9001:2015认证。每台设备出厂前都经过有据可查的工厂验收测试(FAT)，并在整个保修期内提供可追溯的带序列号质量记录。",es:"Certificado ISO 9001:2015 desde 2007. Cada máquina pasa un Test de Aceptación en Fábrica (FAT) documentado antes del envío.",ru:"Сертификат ISO 9001:2015 с 2007 года. Каждая машина проходит задокументированные заводские приёмочные испытания (FAT) перед отгрузкой.",ar:"معتمد ISO 9001:2015 منذ 2007. تخضع كل آلة لاختبار قبول المصنع (FAT) الموثق قبل الشحن.",tr:"2007'den beri ISO 9001:2015 sertifikalı. Her makine sevkiyattan önce belgelenmiş Fabrika Kabul Testinden (FAT) geçer.",fr:"Certifié ISO 9001:2015 depuis 2007. Chaque machine passe un test d'acceptation en usine (FAT) documenté avant expédition.",pt:"Certificado ISO 9001:2015 desde 2007. Cada máquina passa por um Teste de Aceitação de Fábrica (FAT) documentado antes do envio.",hi:"2007 से ISO 9001:2015 प्रमाणित। हर मशीन शिपमेंट से पहले एक प्रलेखित फैक्ट्री स्वीकृति परीक्षण (FAT) पास करती है।",id:"Bersertifikat ISO 9001:2015 sejak 2007. Setiap mesin lulus Uji Penerimaan Pabrik (FAT) yang terdokumentasi sebelum pengiriman."},

